                    c_nv_pr = nv_sp_pr.find('p:cNvPr', namespaces)
                    if c_nv_pr is not None:
                        name = c_nv_pr.get('name', 'unnamed')
                        print(f"  Shape: {name} | Text: {elem.text[:100]}")
PYEOF
done

